	"point_7_summary_1": "\u062A\u0631\u0627\u06A9\u0646\u0634\u200C\u0647\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0645\u0642\u0627\u0648\u0645 \u062F\u0631 \u0628\u0631\u0627\u0628\u0631 \u0633\u0627\u0646\u0633\u0648\u0631 \u0647\u0633\u062A\u0646\u062F - \u067E\u0633 \u0627\u0632 \u0627\u0631\u0633\u0627\u0644 \u0628\u0647 \u0634\u0628\u06A9\u0647\u060C \u0647\u06CC\u0686 \u0645\u0631\u062C\u0639 \u0645\u0631\u06A9\u0632\u06CC \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0622\u0646\u0647\u0627 \u0631\u0627 \u0645\u062A\u0648\u0642\u0641 \u06CC\u0627 \u0628\u0631\u06AF\u0631\u062F\u0627\u0646\u062F. \u0628\u0627\u0646\u06A9\u200C\u0647\u0627 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u0646\u062F \u062A\u0631\u0627\u06A9\u0646\u0634\u200C\u0647\u0627 \u0631\u0627 \u0645\u0633\u062F\u0648\u062F\u060C \u0645\u0646\u062C\u0645\u062F\u060C \u0628\u0631\u06AF\u0631\u062F\u0627\u0646\u0646\u062F \u06CC\u0627 \u0645\u062D\u062F\u0648\u062F \u06A9\u0646\u0646\u062F."
