	"crypto_point_1": "\u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u0648 \u0641\u0648\u0631\u06A9\u200C\u0647\u0627\u06CC \u0645\u06A9\u0631\u0631", "crypto_point_2": "\u06A9\u0646\u062A\u0631\u0644 \u0645\u062A\u0645\u0631\u06A9\u0632", "crypto_point_3": "\u0639\u0631\u0636\u0647 \u0646\u0627\u0645\u062D\u062F\u0648\u062F \u06CC\u0627 \u062A\u0648\u0631\u0645\u06CC", "crypto_point_4": "\u067E\u0631\u0648\u062A\u06A9\u0644\u200C\u0647\u0627\u06CC \u067E\u06CC\u0686\u06CC\u062F\u0647", "crypto_point_5": "\u0627\u062C\u0645\u0627\u0639 \u0622\u0632\u0645\u0627\u06CC\u0634\u06CC", "crypto_point_6": "\u062A\u0648\u06A9\u0646\u200C\u0647\u0627\u06CC \u06A9\u0627\u0631\u0628\u0631\u062F\u06CC \u0633\u0648\u062F\u0627\u06AF\u0631\u0627\u0646\u0647", "crypto_point_7": "\u0634\u06A9\u0646\u0646\u062F\u0647 \u0648 \u0622\u0633\u06CC\u0628\u200C\u067E\u0630\u06CC\u0631", "crypto_point_8": "\u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u0634\u0631\u06A9\u062A\u06CC",
	"bitcoin": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646",
	"bitcoin_point_1": "\u067E\u0631\u0648\u062A\u06A9\u0644 \u062A\u063A\u06CC\u06CC\u0631\u0646\u0627\u067E\u0630\u06CC\u0631", "bitcoin_point_2": "\u0648\u0627\u0642\u0639\u0627\u064B \u063A\u06CC\u0631\u0645\u062A\u0645\u0631\u06A9\u0632", "bitcoin_point_3": "\u0639\u0631\u0636\u0647 \u062B\u0627\u0628\u062A \u06F2\u06F1 \u0645\u06CC\u0644\u06CC\u0648\u0646 BTC", "bitcoin_point_4": "\u0633\u0627\u062F\u0647 \u0648 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633", "bitcoin_point_5": "\u0627\u062B\u0628\u0627\u062A \u06A9\u0627\u0631 \u0622\u0632\u0645\u0648\u062F\u0647 \u0634\u062F\u0647", "bitcoin_point_6": "\u067E\u0648\u0644 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u062E\u0627\u0644\u0635", "bitcoin_point_7": "\u067E\u0627\u062F\u0634\u06A9\u0646\u0646\u062F\u0647", "bitcoin_point_8": "\u0647\u06CC\u0686 \u0646\u0647\u0627\u062F \u0648\u0627\u062D\u062F\u06CC \u06A9\u0646\u062A\u0631\u0644\u0634 \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F",
	"point_1_summary_1": "\u067E\u0631\u0648\u062A\u06A9\u0644 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0627\u0632 \u0633\u0627\u0644 \u06F2\u06F0\u06F0\u06F9 \u0627\u0633\u0627\u0633\u0627\u064B \u0628\u062F\u0648\u0646 \u062A\u063A\u06CC\u06CC\u0631 \u0628\u0627\u0642\u06CC \u0645\u0627\u0646\u062F\u0647 \u0627\u0633\u062A. \u0628\u06CC\u0634\u062A\u0631 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0645\u06A9\u0631\u0631\u0627\u064B \u067E\u0631\u0648\u062A\u06A9\u0644 \u062E\u0648\u062F \u0631\u0627 \u062A\u063A\u06CC\u06CC\u0631 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F.",
	"point_2_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0631\u0648\u06CC \u06CC\u06A9 \u0634\u0628\u06A9\u0647 \u0648\u0627\u0642\u0639\u0627\u064B \u063A\u06CC\u0631\u0645\u062A\u0645\u0631\u06A9\u0632 \u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u062A\u0648\u0633\u0637 \u0628\u0646\u06CC\u0627\u062F\u0647\u0627\u060C \u0634\u0631\u06A9\u062A\u200C\u0647\u0627 \u06CC\u0627 \u06AF\u0631\u0648\u0647\u200C\u0647\u0627\u06CC \u06A9\u0648\u0686\u06A9 \u062A\u0648\u0633\u0639\u0647\u200C\u062F\u0647\u0646\u062F\u0647 \u06A9\u0646\u062A\u0631\u0644 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
	"point_3_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0633\u0642\u0641 \u0633\u062E\u062A \u06F2\u06F1 \u0645\u06CC\u0644\u06CC\u0648\u0646 \u0633\u06A9\u0647 \u062F\u0627\u0631\u062F \u06A9\u0647 \u0622\u0646 \u0631\u0627 \u06A9\u0645\u06CC\u0627\u0628\u200C\u062A\u0631\u06CC\u0646 \u062F\u0627\u0631\u0627\u06CC\u06CC \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0628\u06CC\u0634\u062A\u0631 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0639\u0631\u0636\u0647 \u0646\u0627\u0645\u062D\u062F\u0648\u062F \u062F\u0627\u0631\u0646\u062F.",
	"point_4_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u06CC\u06A9 \u0647\u062F\u0641 \u0633\u0627\u062F\u0647 \u062F\u0627\u0631\u062F: \u067E\u0648\u0644 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0647\u0645\u062A\u0627 \u0628\u0647 \u0647\u0645\u062A\u0627. \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0634\u0627\u0645\u0644 \u0642\u0631\u0627\u0631\u062F\u0627\u062F\u0647\u0627\u06CC \u0647\u0648\u0634\u0645\u0646\u062F \u067E\u06CC\u0686\u06CC\u062F\u0647 \u0647\u0633\u062A\u0646\u062F.",
	"point_5_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0627\u0632 \u0627\u062C\u0645\u0627\u0639 \u0627\u062B\u0628\u0627\u062A \u06A9\u0627\u0631 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F \u06A9\u0647 \u0628\u06CC\u0634 \u0627\u0632 \u06F1\u06F5 \u0633\u0627\u0644 \u0622\u0632\u0645\u0627\u06CC\u0634 \u0634\u062F\u0647 \u0627\u0633\u062A. \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0627\u0632 \u0645\u06A9\u0627\u0646\u06CC\u0632\u0645\u200C\u0647\u0627\u06CC \u0622\u0632\u0645\u0627\u06CC\u0634\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F.",
	"point_6_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u067E\u0648\u0644 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0628\u06CC\u0634\u062A\u0631 \u062A\u0648\u06A9\u0646\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u062A\u0648\u06A9\u0646\u200C\u0647\u0627\u06CC \u06A9\u0627\u0631\u0628\u0631\u062F\u06CC \u06CC\u0627 \u0633\u0648\u062F\u0627\u06AF\u0631\u0627\u0646\u0647 \u0647\u0633\u062A\u0646\u062F.",
	"point_7_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0632\u06CC\u0631 \u062D\u0645\u0644\u0647 \u0642\u0648\u06CC\u200C\u062A\u0631 \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0627\u0632 \u0647\u0631 \u0628\u062D\u0631\u0627\u0646\u06CC \u062C\u0627\u0646 \u0633\u0627\u0644\u0645 \u0628\u0647 \u062F\u0631 \u0628\u0631\u062F\u0647 \u0627\u0633\u062A. \u0628\u06CC\u0634\u062A\u0631 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0634\u06A9\u0646\u0646\u062F\u0647 \u0647\u0633\u062A\u0646\u062F.",
	"point_8_summary_1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0647\u06CC\u0686 \u0645\u062F\u06CC\u0631\u0639\u0627\u0645\u0644\u06CC\u060C \u0647\u06CC\u0686 \u0634\u0631\u06A9\u062A\u06CC \u067E\u0634\u062A\u0634 \u0648 \u0647\u06CC\u0686 \u0646\u0642\u0637\u0647 \u0634\u06A9\u0633\u062A \u0648\u0627\u062D\u062F\u06CC \u0646\u062F\u0627\u0631\u062F. \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u067E\u0631\u0648\u0698\u0647\u200C\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u062A\u0648\u0633\u0637 \u0634\u0631\u06A9\u062A\u200C\u0647\u0627\u06CC \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u0645\u06CC\u200C\u0634\u0648\u0646\u062F."
